 return KB.observations.map((r,i)=>({r,i,score:terms[actor].reduce((n,t)=>n+((r.actor+' '+r.summary+' '+r.topics).toLowerCase().includes(t.toLowerCase())?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.i-b.i).slice(0,12).map(x=>x.r);
